 static int n;static void eq(String a,double b){if(Math.abs(Double.parseDouble(a)-b)>0.00011*Math.max(1,Math.abs(b)))throw new AssertionError(a+" != "+b);n++;}
 static void ok(boolean b){if(!b)throw new AssertionError();n++;}static void bad(Runnable r){try{r.run();throw new AssertionError("expected error");}catch(IllegalArgumentException|ArithmeticException e){n++;}}
 static String c(String name,String... v){return calc(name,v,0);}
 public static void main(String[]args){eq(tax(dec("10000"),dec("7"),false).toPlainString(),10700);eq(tax(dec("10700"),dec("7"),true).toPlainString(),10000);eq(payment(dec("12000"),dec("0"),dec("12")).toPlainString(),1000);eq(payment(dec("100000"),dec("12"),dec("12")).toPlainString(),8884.8788678);eq(npv(dec("10"),cash("-100;110")).toPlainString(),0);eq(irr(cash("-100;110")).toPlainString(),10);bad(()->irr(cash("-100;230;-132")));bad(()->payment(dec("100"),dec("5"),dec("0")));bad(()->tax(dec("100"),dec("-7"),false));eq(c("Discount","1000","10","20"),720);eq(c("Markup / Markdown","100","25","20"),100);eq(c("Unit Cost","1200","12"),100);ok(c("Break-even","1000","60","40").equals("50 units"));ok(c("Profit & Margin","100","125").contains("Margin: 20%"));ok(c("VAT","100","7").contains("Add VAT: 107"));ok(c("Withholding Tax","10000","3").contains("Net paid: 9700"));ok(c("ROI","100","125").equals("25%"));ok(c("CAGR","100","121","2").equals("10%"));eq(c("Simple Interest","1000","10","2"),1200);eq(c("Compound Interest","1000","10","2"),1210);ok(c("Depreciation","10000","1000","3").equals("3000 / year"));ok(c("Payback Period","-100;60;80").equals("1.5 periods"));ok(c("Amortization","1200","0","12").contains("12: P 100 / I 0 / Bal 0"));eq(calc("Time Value of Money",new String[]{"-100","0","0","2","10"},0),121);eq(calc("Time Value of Money",new String[]{"0","121","0","2","10"},1),-100);eq(calc("Time Value of Money",new String[]{"-100","121","0","0","10"},3),2);eq(calc("Time Value of Money",new String[]{"-100","121","0","2","0"},4),10);ok(money(dec("1.235"),2,RoundingMode.HALF_UP).equals("1.24"));ok(money(dec("1.239"),2,RoundingMode.DOWN).equals("1.23"));bad(()->c("Unit Cost","100","0"));System.out.println("FinancialMathTest: "+n+" passed");}
